actions.script:
const startUser = ec.user.username || null
// the repositories first, committed, so the push log of the commits after (its own transaction) finds them
for (const name of ['repositories', 'iron', 'acme']) {
    ec.message.pushErrors()
    try {
        ec.service.sync().name('ironstone.projects.CodeDemoServices.load#CodeDemoPart').parameter('part', name).requireNewTransaction(true).call()
        if (ec.message.hasError()) throw new Error(ec.message.getErrorsString())
    } catch (err) {
        ec.logger.error(`Code demo: the part ${name} was not loaded: ${err && err.message ? err.message : err}`)
    } finally {
        ec.message.clearErrors()
        ec.message.popErrors()
        if (ec.user.username && ec.user.username !== startUser) ec.user.logoutUser()
        ec.user.setEffectiveTime(null)
    }
}

const GIT = 'org.moqui.git.GitServices'
const users = {john: 'john.doe', joe: 'joe.developer', bob: 'bob.developer'}
const ids = {john: 'EX_JOHN_DOE', joe: 'ORG_ZIZI_JD', bob: 'ORG_ZIZI_BD'}
const account = (userId) => ec.entity.find('moqui.security.UserAccount').condition('userId', userId).disableAuthz().one()
if (account(ids.john) == null) { ec.logger.warn('The code demo needs the user john.doe (mr-mantle demo data); nothing loaded'); return }
const nowMs = Date.now()
const day = 86400000
const call = (name, parameters) => {
    const out = ec.service.sync().name(name).parameters(parameters || {}).call()
    if (ec.message.hasError()) throw new Error(`${name}: ${ec.message.getErrorsString()}`)
    return out || {}
}
const as = (who, daysAgo, run) => {
    if (account(ids[who]) == null) who = 'john'
    ec.user.internalLoginUser(users[who])
    ec.user.setEffectiveTime(nowMs - Math.round(daysAgo * day))
    try { return run() } finally { ec.user.setEffectiveTime(null); ec.user.logoutUser() }
}
const row = (repositoryId) => ec.entity.find('moqui.resource.GitRepository').condition('repositoryId', repositoryId).disableAuthz().one()
const exists = (repositoryId) => row(repositoryId) != null
const empty = (repositoryId) => exists(repositoryId) && !row(repositoryId).headCommitId
const commit = (repositoryId, message, fileMap) => call(`${GIT}.commit#GitFiles`, {repositoryId, message, fileMap}).commitId
// a commit on a branch: the branch is the repository's default for the moment
const commitOn = (repositoryId, branch, message, fileMap) => {
    call(`${GIT}.update#GitRepository`, {repositoryId, branch})
    try { return commit(repositoryId, message, fileMap) } finally { call(`${GIT}.update#GitRepository`, {repositoryId, branch: 'main'}) }
}
const project = (workEffortId) => ec.entity.find('mantle.work.effort.WorkEffort').condition('workEffortId', workEffortId).disableAuthz().one()
const wasDisabled = ec.artifactExecution.disableAuthz()
try {
    if (part === 'repositories') {
        if (!exists('iron') && project('IRON') != null) as('john', 20, () => call('mantle.work.GitServices.create#ProjectRepository', {workEffortId: 'IRON',
            repositoryId: 'iron', repositoryKind: 'db', description: 'IronStone Projects, the app', applyDefaults: false}))
        if (!exists('acme-portal') && project('ACME') != null) as('john', 30, () => call('mantle.work.GitServices.create#ProjectRepository', {workEffortId: 'ACME',
            repositoryId: 'acme-portal', repositoryKind: 'db', description: 'The Acme customer portal', applyDefaults: false}))
    }
    if (part === 'iron') {
        if (!empty('iron')) return
        as('joe', 18, () => commit('iron', 'Start the IronStone Projects app', {
            'README.md': '# IronStone Projects\n\nThe app for project managers, software teams, consultants and their clients: projects and work items, ' +
                'code, time and billing in one place.\n\n## Layout\n\n- `screen/` the screens\n- `service/` the services\n- `data/` the seed and demo data\n\n' +
                'Work items are keyed by the project, as `IRON-12`; name one in a commit message to link the commit to it.\n',
            '.gitignore': '/build/\n*.log\n',
            'screen/Projects.xml': '<?xml version="1.0" encoding="UTF-8"?>\n<screen default-menu-title="IronStone Projects">\n    <subscreens default-item="Home"/>\n' +
                '    <widgets><subscreens-panel id="projects-panel" type="popup"/></widgets>\n</screen>\n'}))
        as('joe', 15, () => commit('iron', 'IRON-2 Work item tree view: the first level', {
            'src/tree.js': '// the work item tree: one level at a time\nexport function loadLevel(parentId) {\n    return fetch(`/items?parent=${parentId}`)\n' +
                '        .then((response) => response.json())\n}\n'}))
        as('john', 10, () => commit('iron', 'Board grouped by assignee (IRON-5)', {
            'src/board.js': '// the board, grouped by a field\nexport function groupBy(items, field) {\n    const groups = new Map()\n' +
                '    for (const item of items) {\n        const key = item[field] ?? \'none\'\n        if (!groups.has(key)) groups.set(key, [])\n' +
                '        groups.get(key).push(item)\n    }\n    return groups\n}\n'}))
        const tagged = as('john', 9, () => call(`${GIT}.create#GitRef`, {repositoryId: 'iron', refName: 'IRON/v0.1', refType: 'tag', message: 'The first preview'}))
        // IRON's documentation beside the code, before IRON-3 (so the head of main stays that commit)
        try {
            if (ec.entity.find('mantle.work.effort.WorkEffortSetting').condition({workEffortId: 'IRON', settingTypeEnumId: 'WstDocsWikiSpace'}).one() == null) {
                const spaceId = as('john', 8.5, () => call('mantle.work.ProjectServices.create#ProjectDocsSpace', {workEffortId: 'IRON', storage: 'repository', repositoryId: 'iron'}).wikiSpaceId)
                const page = (who, daysAgo, pageName, pageText, versionNote) => as(who, daysAgo, () => call('org.moqui.resource.WikiServices.update#WikiPage',
                    {wikiSpaceId: spaceId, pageName, pageText, versionNote}))
                page('john', 8, 'Getting started', '# Getting started\n\nClone the repository, load the demo and open Projects:\n\n```\ngit clone https://git.example.com/git/iron\n./moq load\n./moq run\n```\n\n'
                    + 'Work items are keyed `IRON-n`; name one in a commit message or a branch (`IRON-7-timer`) to link it. See [Architecture](Architecture).\n', 'Getting started')
                page('joe', 7.5, 'Architecture', '# Architecture\n\n- **Screens** in `screen/`, one per design section.\n- **Services** in `service/`, the Mantle records underneath.\n'
                    + '- **Data** in `data/`: seed and demo.\n\nThe work item tree loads a level at a time (`src/tree.js`).\n', 'Architecture')
                page('joe', 7, 'Getting started', '# Getting started\n\nClone the repository, load the demo and open Projects:\n\n```\ngit clone https://git.example.com/git/iron\n./moq load\n./moq run\n```\n\n'
                    + 'Work items are keyed `IRON-n`; name one in a commit message or a branch (`IRON-7-timer`) to link it. See [Architecture](Architecture).\n\n'
                    + 'Sign in as `john.doe` for the manager\u2019s view, or `joe.developer` for a developer\u2019s.\n', 'Sign-in users')
                const build = ec.entity.find('moqui.resource.wiki.WikiPage').condition({wikiSpaceId: 'BOSSENG', pagePath: 'Build setup'}).disableAuthz().one()
                if (build != null && ec.entity.find('mantle.work.effort.WikiPageWorkEffort').condition({wikiPageId: build.wikiPageId, workEffortId: 'IRON'}).count() === 0)
                    call('create#mantle.work.effort.WikiPageWorkEffort', {wikiPageId: build.wikiPageId, workEffortId: 'IRON'})
            }
        } catch (err) {
            ec.message.clearErrors()
            ec.logger.error(`Code demo: IRON's documentation space was not made: ${err && err.message ? err.message : err}`)
        }
        const mainHead = as('joe', 6, () => commit('iron', 'IRON-3 Expand and collapse rows', {
            'src/tree.js': '// the work item tree: one level at a time\nexport function loadLevel(parentId) {\n    return fetch(`/items?parent=${parentId}`)\n' +
                '        .then((response) => response.json())\n}\n\n// a row opens to its children and closes again\nexport function toggle(row) {\n' +
                '    row.expanded = !row.expanded\n    return row.expanded ? loadLevel(row.id) : Promise.resolve([])\n}\n'}))
        as('john', 6, () => call(`${GIT}.store#GitBranchRule`, {repositoryId: 'iron', refPattern: 'main', allowForcePush: 'N', allowDelete: 'N', requiredApprovals: 1}))
        as('joe', 5, () => call(`${GIT}.create#GitRef`, {repositoryId: 'iron', refName: 'IRON-3-expand-collapse', refType: 'branch'}))
        as('joe', 3, () => commitOn('iron', 'IRON-3-expand-collapse', 'IRON-3 Remember the expanded rows', {
            'src/tree.js': '// the work item tree: one level at a time\nexport function loadLevel(parentId) {\n    return fetch(`/items?parent=${parentId}`)\n' +
                '        .then((response) => response.json())\n}\n\nconst expanded = new Set(JSON.parse(localStorage.getItem(\'tree.expanded\') || \'[]\'))\n\n' +
                '// a row opens to its children and closes again, and is remembered\nexport function toggle(row) {\n    row.expanded = !row.expanded\n' +
                '    if (row.expanded) expanded.add(row.id); else expanded.delete(row.id)\n    localStorage.setItem(\'tree.expanded\', JSON.stringify([...expanded]))\n' +
                '    return row.expanded ? loadLevel(row.id) : Promise.resolve([])\n}\n'}))
        const branchHead = as('joe', 1, () => commitOn('iron', 'IRON-3-expand-collapse', 'IRON-3 Left and right arrows close and open a row', {
            'src/keys.js': '// the tree\'s keys\nexport function onKey(event, row, toggle) {\n    if (event.key === \'ArrowRight\' && !row.expanded) toggle(row)\n' +
                '    if (event.key === \'ArrowLeft\' && row.expanded) toggle(row)\n}\n'}))
        as('bob', 4, () => call(`${GIT}.create#GitRef`, {repositoryId: 'iron', refName: 'IRON-7-timer', refType: 'branch', revision: mainHead}))
        const timerHead = as('bob', 2, () => commitOn('iron', 'IRON-7-timer', 'IRON-7 Timer in the header: start and stop', {
            'src/timer.js': '// the running timer of the header\nlet startedAt = null\nexport const start = () => { startedAt = Date.now() }\n' +
                'export const stop = () => { const ms = Date.now() - startedAt; startedAt = null; return ms }\n'}))
        // checks as outside CI posts them; the failure by its author, so no one else is told of it in the demo
        as('john', 6, () => call(`${GIT}.create#GitCommitStatus`, {repositoryId: 'iron', commitId: mainHead, state: 'success', context: 'ci/build',
            description: 'Build and tests passed', targetUrl: 'https://ci.example.com/iron/builds/41'}))
        as('john', 1, () => call(`${GIT}.create#GitCommitStatus`, {repositoryId: 'iron', commitId: branchHead, state: 'success', context: 'ci/build',
            description: 'Build and tests passed', targetUrl: 'https://ci.example.com/iron/builds/44'}))
        as('bob', 2, () => call(`${GIT}.create#GitCommitStatus`, {repositoryId: 'iron', commitId: timerHead, state: 'failure', context: 'ci/build',
            description: '2 tests failed', targetUrl: 'https://ci.example.com/iron/builds/43'}))
        // the merge request, its reviewer asked without the notice a request sends
        const mr = as('joe', 1, () => call('org.moqui.git.GitReviewServices.create#MergeRequest', {repositoryId: 'iron', sourceRef: 'IRON-3-expand-collapse',
            targetRef: 'main', title: 'Expand and collapse rows (IRON-3)', description: 'The tree remembers which rows are open, and the arrow keys open and close them.\n\nCloses IRON-3'}))
        const reviewer = ec.entity.makeValue('moqui.resource.GitMergeRequestReviewer')
        reviewer.setFields({mergeRequestId: mr.mergeRequestId, userId: ids.john, statusId: 'GmrrRequested', requestedDate: ec.user.nowTimestamp}, true, null, null)
        reviewer.create()
        // a review thread on a line of src/tree.js: john asks, joe answers (as create#ReviewComment files them, without its notices)
        const comment = (who, daysAgo, body, parent) => as(who, daysAgo, () => {
            const id = call('create#mantle.party.communication.CommunicationEvent', {communicationEventTypeId: 'Comment', contactMechTypeEnumId: 'CmtWebForm',
                statusId: 'CeSent', fromPartyId: ec.user.userAccount?.partyId || null, entryDate: ec.user.nowTimestamp, contentType: 'text/markdown',
                subject: 'Review of !' + mr.mergeRequestNum + (parent ? '' : ' src/tree.js:7'), body, parentCommEventId: parent || null,
                rootCommEventId: parent || null}).communicationEventId
            if (!parent) {
                call('create#mantle.party.communication.CommunicationEventRecord', {communicationEventId: id, recordEntityName: 'moqui.resource.GitMergeRequest',
                    recordId: mr.mergeRequestId, linkedByUserId: ec.user.userId, linkedDate: ec.user.nowTimestamp})
                call('mantle.work.GitServices.store#ReviewAnchor', {communicationEventId: id, mergeRequestId: mr.mergeRequestId, path: 'src/tree.js', newLine: 7,
                    lineText: "const expanded = new Set(JSON.parse(localStorage.getItem('tree.expanded') || '[]'))"})
            }
            return id
        })
        const thread = comment('john', 0.5, 'Should the open rows be kept **per project**? Two projects\' trees share this key now.', null)
        comment('joe', 0.3, 'Good point: I will add the project to the key.', thread)
        if (!tagged.refName) ec.logger.warn('Code demo: the tag IRON/v0.1 was not made')
    }
    if (part === 'acme') {
        if (!empty('acme-portal')) return
        as('joe', 28, () => commit('acme-portal', 'The portal skeleton for ACME-1', {
            'README.md': '# Acme customer portal\n\nSign-in, order history and invoices for Acme\'s customers.\n',
            'src/signin.html': '<form method="post" action="/signin">\n  <input name="username" autocomplete="username">\n  <input name="password" type="password" autocomplete="current-password">\n  <button>Sign in</button>\n</form>\n'}))
        as('joe', 12, () => commit('acme-portal', 'ACME-3 Single sign-on: read the directory settings', {
            'src/sso.js': '// single sign-on with the customer\'s directory\nexport const settings = { issuer: \'https://login.acme.example\', clientId: \'portal\' }\n'}))
        as('john', 12, () => call(`${GIT}.create#GitRef`, {repositoryId: 'acme-portal', refName: 'ACME/v0.1', refType: 'tag', message: 'Shown to Acme'}))
    }
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
